def is_balanced(text):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = {'(', '[', '{'}
    for char in text:
        if char in openers:
            stack.append(char)
        elif char in pairs:
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()
    return len(stack) == 0
